
-- AI Medical Assistant PostgreSQL initialization
--
-- This script runs when PostgreSQL initializes a NEW data directory.
-- Application tables are created and updated by Alembic migrations.
--
-- UUID values are generated by the application in Python, so no
-- PostgreSQL UUID-generation extension is required by this setup.
--
-- Do not put passwords or other secrets in this file.

-- Set a predictable default for this initialization session.
SET TIME ZONE 'UTC';

